class Solution {
public:
    int distinctSequences(int n) {
        if (n == 1) return 6;
        long long MOD = 1e9 + 7;
        long long dp[7][7] = {0};
        for (int i = 1; i <= 6; ++i) {
            for (int j = 1; j <= 6; ++j) {
                if (i != j && std::gcd(i, j) == 1) dp[j][i] = 1;
            }
        }
        for (int step = 3; step <= n; ++step) {
            long long next_dp[7][7] = {0};
            for (int prev = 1; prev <= 6; ++prev) {
                for (int pp = 1; pp <= 6; ++pp) {
                    if (dp[prev][pp] == 0) continue;
                    for (int curr = 1; curr <= 6; ++curr) {
                        if (curr != prev && curr != pp && std::gcd(curr, prev) == 1) {
                            next_dp[curr][prev] = (next_dp[curr][prev] + dp[prev][pp]) % MOD;
                        }
                    }
                }
            }
            std::memcpy(dp, next_dp, sizeof(dp));
        }
        long long ans = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = 1; j <= 6; ++j) ans = (ans + dp[i][j]) % MOD;
        }
        return ans;
    }
};

class Solution {
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    public int distinctSequences(int n) {
        if (n == 1) return 6;
        long MOD = 1_000_000_007L;
        long[][] dp = new long[7][7];
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6; j++) {
                if (i != j && gcd(i, j) == 1) dp[j][i] = 1;
            }
        }
        for (int step = 3; step <= n; step++) {
            long[][] nextDp = new long[7][7];
            for (int prev = 1; prev <= 6; prev++) {
                for (int pp = 1; pp <= 6; pp++) {
                    if (dp[prev][pp] == 0) continue;
                    for (int curr = 1; curr <= 6; curr++) {
                        if (curr != prev && curr != pp && gcd(curr, prev) == 1) {
                            nextDp[curr][prev] = (nextDp[curr][prev] + dp[prev][pp]) % MOD;
                        }
                    }
                }
