var distinctSequences = function(n) {
    if (n === 1) return 6;
    const MOD = 1000000007;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let dp = Array.from({ length: 7 }, () => new Int32Array(7));
    for (let i = 1; i <= 6; i++) {
        for (let j = 1; j <= 6; j++) {
            if (i !== j && gcd(i, j) === 1) dp[j][i] = 1;
        }
    }
    for (let step = 3; step <= n; step++) {
        const nextDp = Array.from({ length: 7 }, () => new Int32Array(7));
        for (let prev = 1; prev <= 6; prev++) {
            for (let pp = 1; pp <= 6; pp++) {
                if (dp[prev][pp] === 0) continue;
                for (let curr = 1; curr <= 6; curr++) {
                    if (curr !== prev && curr !== pp && gcd(curr, prev) === 1) {
                        nextDp[curr][prev] = (nextDp[curr][prev] + dp[prev][pp]) % MOD;
                    }
                }
            }
        }
        dp = nextDp;
    }
    let ans = 0;
    for (let i = 1; i <= 6; i++) {
        for (let j = 1; j <= 6; j++) ans = (ans + dp[i][j]) % MOD;
    }
    return ans;
};
